const paymentTotals = `-- name: PaymentTotals :many
SELECT currency, count(*) AS n, CAST(COALESCE(sum(amount), 0) AS BIGINT) AS total
FROM payments WHERE status = 'applied' AND applied_at >= $1 GROUP BY currency
`

type PaymentTotalsRow struct {
	Currency string
	N        int64
	Total    int64
}

func (q *Queries) PaymentTotals(ctx context.Context, appliedAt sql.NullInt64) ([]PaymentTotalsRow, error) {
	rows, err := q.db.QueryContext(ctx, paymentTotals, appliedAt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PaymentTotalsRow{}
	for rows.Next() {
		var i PaymentTotalsRow
		if err := rows.Scan(&i.Currency, &i.N, &i.Total); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

