const takeUserExtraDevice = `-- name: TakeUserExtraDevice :one
UPDATE users
SET device_limit = CASE WHEN device_limit IS NULL THEN NULL ELSE GREATEST(device_limit - 1, 1) END,
    extra_devices = extra_devices - 1, updated_at = $1
WHERE id = $2 AND extra_devices > 0
RETURNING id, name, contact, note, tags, status, tariff_id, traffic_limit, device_limit, reset_strategy, period_days, period_start, used_up, used_down, total_up, total_down, expires_at, inbounds, sub_token, slot_id, online_at, created_at, updated_at, billing_day, source, hidden, folder_id, speed_limit, device_mode, extra_devices, extra_devices_until, device_pack_id
`

type TakeUserExtraDeviceParams struct {
	UpdatedAt int64
	ID        int64
}

// A refunded place goes back; the limit never falls under one.
func (q *Queries) TakeUserExtraDevice(ctx context.Context, arg TakeUserExtraDeviceParams) (User, error) {
	row := q.db.QueryRowContext(ctx, takeUserExtraDevice, arg.UpdatedAt, arg.ID)
	var i User
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Contact,
		&i.Note,
		&i.Tags,
		&i.Status,
		&i.TariffID,
		&i.TrafficLimit,
		&i.DeviceLimit,
		&i.ResetStrategy,
		&i.PeriodDays,
		&i.PeriodStart,
		&i.UsedUp,
		&i.UsedDown,
		&i.TotalUp,
		&i.TotalDown,
		&i.ExpiresAt,
		&i.Inbounds,
		&i.SubToken,
		&i.SlotID,
		&i.OnlineAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.BillingDay,
		&i.Source,
		&i.Hidden,
		&i.FolderID,
		&i.SpeedLimit,
		&i.DeviceMode,
		&i.ExtraDevices,
		&i.ExtraDevicesUntil,
		&i.DevicePackID,
	)
	return i, err
}
